+    window: Option<Window>,
+    render_ctx: Option<xgame_render::RenderContext>,
+    pipeline: Option<wgpu::RenderPipeline>,
+    vertex_buffer: Option<wgpu::Buffer>,
+    num_vertices: u32,
+}
+
+impl State {
+    fn new() -> Self {
+        Self {
+            window: None,
+            render_ctx: None,
+            pipeline: None,
+            vertex_buffer: None,
+            num_vertices: 0,
+        }
+    }
+
+    fn init_gpu(&mut self) {
+        let window = self.window.as_ref().unwrap();
+        let ctx = pollster::block_on(xgame_render::RenderContext::new(window));
+
+        let shader = ctx
+            .device
+            .create_shader_module(wgpu::ShaderModuleDescriptor {
+                label: Some("Triangle shader"),
+                source: wgpu::ShaderSource::Wgsl(Cow::Borrowed(SHADER)),
+            });
+
+        let vertex_buffer = ctx.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
+            label: Some("Vertex buffer"),
+            contents: bytemuck::cast_slice(VERTICES),
+            usage: wgpu::BufferUsages::VERTEX,
+        });
+
+        let pipeline_layout = ctx
+            .device
+            .create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
+                label: Some("Pipeline layout"),
+                bind_group_layouts: &[],
+                push_constant_ranges: &[],
+            });
+
+        let pipeline = ctx
+            .device
+            .create_render_pipeline(&wgpu::RenderPipelineDescriptor {
+                label: Some("Triangle pipeline"),
+                layout: Some(&pipeline_layout),
+                vertex: wgpu::VertexState {
+                    module: &shader,
+                    entry_point: Some("vs_main"),
+                    compilation_options: Default::default(),
+                    buffers: &[wgpu::VertexBufferLayout {
+                        array_stride: std::mem::size_of::<Vertex>() as wgpu::BufferAddress,
+                        step_mode: wgpu::VertexStepMode::Vertex,
+                        attributes: &wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x3],
+                    }],
+                },
+                fragment: Some(wgpu::FragmentState {
+                    module: &shader,
+                    entry_point: Some("fs_main"),
+                    compilation_options: Default::default(),
+                    targets: &[Some(wgpu::ColorTargetState {
+                        format: ctx.config.format,
+                        blend: Some(wgpu::BlendState::REPLACE),
+                        write_mask: wgpu::ColorWrites::ALL,
+                    })],
+                }),
+                primitive: wgpu::PrimitiveState {
+                    topology: wgpu::PrimitiveTopology::TriangleList,
+                    ..Default::default()
+                },
+                depth_stencil: None,
+                multisample: wgpu::MultisampleState::default(),
+                multiview: None,
+                cache: None,
+            });
+
+        self.render_ctx = Some(ctx);
+        self.pipeline = Some(pipeline);
+        self.vertex_buffer = Some(vertex_buffer);
+        self.num_vertices = VERTICES.len() as u32;
+    }
+
+    fn render(&mut self) {
+        let ctx = self.render_ctx.as_ref().unwrap();
+        let pipeline = self.pipeline.as_ref().unwrap();
+        let vertex_buffer = self.vertex_buffer.as_ref().unwrap();
+
+        let output = ctx.surface.get_current_texture().expect("get_current_texture");
+        let view = output
+            .texture
+            .create_view(&wgpu::TextureViewDescriptor::default());
+
+        let mut encoder = ctx
+            .device
+            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
+                label: Some("Triangle encoder"),
+            });
+
+        {
+            let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
+                label: Some("Triangle pass"),
+                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
+                    view: &view,
+                    resolve_target: None,
+                    ops: wgpu::Operations {
+                        load: wgpu::LoadOp::Clear(wgpu::Color {
+                            r: 0.1,
+                            g: 0.1,
+                            b: 0.15,
+                            a: 1.0,
+                        }),
+                        store: wgpu::StoreOp::Store,
+                    },
+                })],
+                depth_stencil_attachment: None,
+                timestamp_writes: None,
+                occlusion_query_set: None,
+            });
+
+            rpass.set_pipeline(pipeline);
+            rpass.set_vertex_buffer(0, vertex_buffer.slice(..));
+            rpass.draw(0..self.num_vertices, 0..1);
+        }
+
+        ctx.queue.submit(std::iter::once(encoder.finish()));
+        output.present();
+    }
+}
+
+// ---------------------------------------------------------------------------
+// Event loop
+// ---------------------------------------------------------------------------
+
+fn main() {
+    env_logger::init();
+    let event_loop = EventLoop::new().unwrap();
+    event_loop.set_control_flow(ControlFlow::Poll);
+
+    let mut state = State::new();
+    event_loop.run_app(&mut state).unwrap();
+}
+
+impl ApplicationHandler for State {
+    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
+        if self.window.is_none() {
+            let attr = Window::default_attributes()
+                .with_title("XGameEngine — Triangle")
+                .with_inner_size(winit::dpi::LogicalSize::new(800, 600));
+            let window = event_loop.create_window(attr).unwrap();
+            self.window = Some(window);
+            self.init_gpu();
+        }
+    }
+
+    fn window_event(
+        &mut self,
+        event_loop: &ActiveEventLoop,
+        _window_id: WindowId,
+        event: WindowEvent,
+    ) {
+        if let WindowEvent::CloseRequested = event {
+            event_loop.exit();
+            return;
+        }
+
+        if self.render_ctx.is_some() {
+            match event {
+                WindowEvent::Resized(physical_size) => {
+                    self.render_ctx
+                        .as_mut()
+                        .unwrap()
+                        .resize((physical_size.width, physical_size.height));
+                }
+                WindowEvent::RedrawRequested => {
+                    self.render();
+                    self.window.as_ref().unwrap().request_redraw();
+                }
+                _ => {}
+            }
+        }
+    }
+}

