use anyhow::{Context, Result};
use std::path::Path;

/// One draw-call from a glTF mesh primitive.
pub struct GltfPrimitive {
    pub vertex_buffer: wgpu::Buffer,
    pub index_buffer: Option<wgpu::Buffer>,
    pub num_indices: u32,
    pub index_format: wgpu::IndexFormat,
    pub num_vertices: u32,
}

/// A collection of GPU-resident primitives loaded from a glTF file.
pub struct GltfMesh {
    pub primitives: Vec<GltfPrimitive>,
    /// Vertex stride in bytes (uniform across all primitives).
    pub vertex_size: u64,
}

// ---------------------------------------------------------------------------
// Host-side vertex (position + normal + colour)
// ---------------------------------------------------------------------------

#[repr(C)]
#[derive(Copy, Clone, Debug, bytemuck::Pod, bytemuck::Zeroable)]
pub struct GltfVertex {
    pub position: [f32; 3],
    pub normal: [f32; 3],
    pub color: [f32; 3],
}

impl GltfVertex {
    pub const STRIDE: wgpu::BufferAddress = std::mem::size_of::<Self>() as wgpu::BufferAddress;

    pub fn layout() -> wgpu::VertexBufferLayout<'static> {
        wgpu::VertexBufferLayout {
            array_stride: Self::STRIDE,
            step_mode: wgpu::VertexStepMode::Vertex,
            attributes: &wgpu::vertex_attr_array![
                0 => Float32x3, // position
                1 => Float32x3, // normal
                2 => Float32x3, // colour
            ],
        }
    }
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

impl GltfMesh {
    /// Load a `.gltf` or `.glb` file and upload all mesh primitives to the GPU.
    ///
    /// Missing vertex attributes are filled with sensible defaults:
    ///   - normal → (0, 0, 1)   [pointing +Z]
    ///   - colour → white        [vertex colours override this if present]
    pub fn from_file(device: &wgpu::Device, path: impl AsRef<Path>) -> Result<Self> {
        let (document, buffers, _images) =
            gltf::import(path.as_ref()).context("Failed to parse glTF file")?;

        let mut primitives = Vec::new();

        for mesh in document.meshes() {
            for primitive in mesh.primitives() {
                let reader = primitive.reader(|buf| {
                    // Resolve buffer index → byte slice
                    Some(&buffers[buf.index()])
                });

                // --- positions (required by glTF spec) ---
                let positions: Vec<[f32; 3]> = reader
                    .read_positions()
                    .context("Mesh primitive has no POSITION attribute")?
                    .collect();

                let vertex_count = positions.len();

                // --- normals (optional) ---
                let normals: Vec<[f32; 3]> = reader
                    .read_normals()
                    .map(|iter| iter.collect())
                    .unwrap_or_else(|| vec![[0.0, 0.0, 1.0]; vertex_count]);

                // --- vertex colours (optional) ---
                let colors: Vec<[f32; 3]> = reader
                    .read_colors(0)
                    .map(|iter| {
                        iter.into_rgb_f32()
                            .map(|c| [c[0], c[1], c[2]])
                            .collect()
                    })
                    .unwrap_or_else(|| vec![[1.0, 1.0, 1.0]; vertex_count]);

                // --- indices (optional) ---
                let indices: Vec<u32> = reader
                    .read_indices()
                    .map(|iter| iter.into_u32().collect())
                    .unwrap_or_else(|| (0..vertex_count as u32).collect());

                // Interleave into GltfVertex array
                let vertices: Vec<GltfVertex> = (0..vertex_count)
                    .map(|i| GltfVertex {
                        position: positions[i],
                        normal: normals[i],
                        color: colors[i],
                    })
                    .collect();

                let vertex_bytes: &[u8] = bytemuck::cast_slice(&vertices);

                let vertex_buffer =
                    device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                        label: Some("glTF vertex buffer"),
                        contents: vertex_bytes,
                        usage: wgpu::BufferUsages::VERTEX,
                    });

                let index_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                    label: Some("glTF index buffer"),
                    contents: bytemuck::cast_slice(&indices),
                    usage: wgpu::BufferUsages::INDEX,
                });

                primitives.push(GltfPrimitive {
                    vertex_buffer,
                    index_buffer: Some(index_buffer),
                    num_indices: indices.len() as u32,
                    index_format: wgpu::IndexFormat::Uint32,
                    num_vertices: vertex_count as u32,
                });
            }
        }

        Ok(Self {
            primitives,
            vertex_size: GltfVertex::STRIDE,
        })
    }
}

use anyhow::{Context, Result};
use std::path::Path;

/// One draw-call from a glTF mesh primitive.
pub struct GltfPrimitive {
    pub vertex_buffer: wgpu::Buffer,
    pub index_buffer: Option<wgpu::Buffer>,
    pub num_indices: u32,
    pub index_format: wgpu::IndexFormat,
    pub num_vertices: u32,
}

/// A collection of GPU-resident primitives loaded from a glTF file.
pub struct GltfMesh {
    pub primitives: Vec<GltfPrimitive>,
    /// Vertex stride in bytes (uniform across all primitives).
    pub vertex_size: u64,
}

// ---------------------------------------------------------------------------
// Host-side vertex (position + normal + colour)
// ---------------------------------------------------------------------------

#[repr(C)]
#[derive(Copy, Clone, Debug, bytemuck::Pod, bytemuck::Zeroable)]
pub struct GltfVertex {
    pub position: [f32; 3],
    pub normal: [f32; 3],
    pub color: [f32; 3],
}

impl GltfVertex {
    pub const STRIDE: wgpu::BufferAddress = std::mem::size_of::<Self>() as wgpu::BufferAddress;

    pub fn layout() -> wgpu::VertexBufferLayout<'static> {
        wgpu::VertexBufferLayout {
            array_stride: Self::STRIDE,
            step_mode: wgpu::VertexStepMode::Vertex,
            attributes: &wgpu::vertex_attr_array![
                0 => Float32x3, // position
                1 => Float32x3, // normal
                2 => Float32x3, // colour
            ],
        }
    }
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

impl GltfMesh {
    /// Load a `.gltf` or `.glb` file and upload all mesh primitives to the GPU.
    ///
    /// Missing vertex attributes are filled with sensible defaults:
    ///   - normal → (0, 0, 1)   [pointing +Z]
    ///   - colour → white        [vertex colours override this if present]
    pub fn from_file(device: &wgpu::Device, path: impl AsRef<Path>) -> Result<Self> {
        let (document, buffers, _images) =
            gltf::import(path.as_ref()).context("Failed to parse glTF file")?;

        let mut primitives = Vec::new();

        for mesh in document.meshes() {
            for primitive in mesh.primitives() {
                let reader = primitive.reader(|buf| {
                    // Resolve buffer index → byte slice
                    Some(&buffers[buf.index()])
                });

                // --- positions (required by glTF spec) ---
                let positions: Vec<[f32; 3]> = reader
                    .read_positions()
                    .context("Mesh primitive has no POSITION attribute")?
                    .collect();

                let vertex_count = positions.len();

                // --- normals (optional) ---
                let normals: Vec<[f32; 3]> = reader
                    .read_normals()
                    .map(|iter| iter.collect())
                    .unwrap_or_else(|| vec![[0.0, 0.0, 1.0]; vertex_count]);

                // --- vertex colours (optional) ---
                let colors: Vec<[f32; 3]> = reader
                    .read_colors(0)
                    .map(|iter| {
                        iter.into_rgb_f32()
                            .map(|c| [c[0], c[1], c[2]])
                            .collect()
                    })
                    .unwrap_or_else(|| vec![[1.0, 1.0, 1.0]; vertex_count]);

                // --- indices (optional) ---
                let indices: Vec<u32> = reader
                    .read_indices()
                    .map(|iter| iter.into_u32().collect())
                    .unwrap_or_else(|| (0..vertex_count as u32).collect());

                // Interleave into GltfVertex array
                let vertices: Vec<GltfVertex> = (0..vertex_count)
                    .map(|i| GltfVertex {
                        position: positions[i],
                        normal: normals[i],
                        color: colors[i],
                    })
                    .collect();

                let vertex_bytes: &[u8] = bytemuck::cast_slice(&vertices);

                let vertex_buffer =
                    device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                        label: Some("glTF vertex buffer"),
                        contents: vertex_bytes,
                        usage: wgpu::BufferUsages::VERTEX,
                    });

                let index_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                    label: Some("glTF index buffer"),
                    contents: bytemuck::cast_slice(&indices),
                    usage: wgpu::BufferUsages::INDEX,
                });

                primitives.push(GltfPrimitive {
                    vertex_buffer,
                    index_buffer: Some(index_buffer),
                    num_indices: indices.len() as u32,
                    index_format: wgpu::IndexFormat::Uint32,
                    num_vertices: vertex_count as u32,
                });
            }
        }

        Ok(Self {
            primitives,
            vertex_size: GltfVertex::STRIDE,
        })
    }
}

